 // Cadastro, edição e exclusão de contatos, sempre limitados à clínica ativa.
 function editContact(id){const c=contacts.find(x=>x.id===id);if(!c)return;$('contact-form').reset();$('contact-edit-id').value=c.id;$('contact-modal-title').textContent='Editar contato';$('contact-name').value=c.full_name||'';$('contact-type').value=c.contact_type||'lead';$('contact-record-status').value=c.status||'new';$('contact-phone').value=c.phone||'';$('contact-email').value=c.email||'';$('contact-source').value=c.source||'';$('contact-followup').value=localInputDate(c.next_follow_up_at);$('contact-consent').checked=!!c.marketing_consent;$('contact-notes').value=c.administrative_notes||'';setStatus('contact-status','');openModal('modal-backdrop')}
 async function deleteRecord(table,id,label){const allowed={clinic_crm_contacts:['owner','admin','manager'],clinic_crm_opportunities:['owner','admin','manager'],clinic_crm_appointments:['owner','admin','manager','reception'],clinic_crm_tasks:['owner','admin','manager'],clinic_crm_interactions:['owner','admin','manager'],clinic_crm_quotes:['owner','admin','manager'],clinic_crm_finance_entries:['owner','admin']}[table]||[];if(!allowed.includes(currentRole)){setStatus('app-status','Seu perfil não tem permissão para excluir este registro.','error');return}if(!confirm('Excluir '+label+'? Esta ação não pode ser desfeita.'))return;try{const {error}=await sb.from(table).delete().eq('id',id).eq('clinic_id',clinicId);if(error)throw error;await audit(label+'_deleted',label,id);await loadData();setStatus('app-status','Registro excluído.','success')}catch(e){setStatus('app-status','Não foi possível excluir. Verifique vínculos e permissões. '+(e.message||''),'error')}}
 $('contacts-table').addEventListener('click',e=>{const b=e.target.closest('[data-contact-action]');if(!b)return;const id=b.dataset.id;if(b.dataset.contactAction==='edit')editContact(id);if(b.dataset.contactAction==='delete')deleteRecord('clinic_crm_contacts',id,'contact')});
 // Oportunidades: CRUD completo e pipeline configurável por clínica.
 function pipelineStages(){const stored=clinicSettings.pipeline_stages;const labels=Array.isArray(stored)?stored:null;const defaults=[{key:'new',label:'Novo contato'},{key:'contacted',label:'Em contato'},{key:'evaluation',label:'Avaliação'},{key:'scheduled',label:'Agendado'},{key:'proposal',label:'Proposta'},{key:'won',label:'Convertida'},{key:'lost',label:'Perdida'}];if(!labels||!labels.length)return defaults;return labels.map((label,i)=>({key:defaults[i]?.key||'custom_'+i,label:String(label)}))}
 function openOpportunityModal(id=''){const o=opportunities.find(x=>x.id===id);$('opportunity-form').reset();$('opportunity-id').value=o?.id||'';$('opportunity-title').textContent=o?'Editar oportunidade':'Nova oportunidade';fillContactSelect('opportunity-contact',o?.contact_id||'');$('opportunity-name').value=o?.title||'';$('opportunity-service').value=o?.service_label||'';$('opportunity-loss-reason').value=o?.loss_reason||'';$('opportunity-value').value=o?.estimated_value??0;$('opportunity-stage').innerHTML=PIPELINE_STAGES.map(s=>'<option value="'+s.key+'">'+esc(s.label)+'</option>').join('');$('opportunity-stage').value=o?.stage||'new';$('opportunity-close').value=o?.expected_close_date||'';setStatus('opportunity-status','');openModal('opportunity-modal')}
 $('opportunity-form').addEventListener('submit',async e=>{e.preventDefault();const btn=$('save-opportunity');btn.disabled=true;try{const id=$('opportunity-id').value;const row={clinic_id:clinicId,contact_id:$('opportunity-contact').value,title:$('opportunity-name').value.trim(),service_label:$('opportunity-service').value.trim()||null,loss_reason:$('opportunity-stage').value==='lost'?($('opportunity-loss-reason').value.trim()||null):null,estimated_value:Number($('opportunity-value').value||0),stage:$('opportunity-stage').value,expected_close_date:$('opportunity-close').value||null,created_by:currentUserId};if(!row.contact_id||!row.title||row.estimated_value<0)throw new Error('Confira contato, título e valor.');const res=id?await sb.from('clinic_crm_opportunities').update(row).eq('id',id).eq('clinic_id',clinicId):await sb.from('clinic_crm_opportunities').insert(row);if(res.error)throw res.error;await audit(id?'opportunity_updated':'opportunity_created','opportunity',id||null,{title:row.title,stage:row.stage});closeModal('opportunity-modal');await loadData();setStatus('app-status','Oportunidade salva.','success')}catch(err){setStatus('opportunity-status','Erro ao salvar: '+(err.message||''),'error')}finally{btn.disabled=false}});
