 // Agenda: valida horários e evita conflito para o mesmo contato/slot quando os dados existentes se sobrepõem.
 function openAppointmentModal(id=''){const a=appointments.find(x=>x.id===id);$('appointment-form').reset();$('appointment-id').value=a?.id||'';$('appointment-title').textContent=a?'Editar agendamento':'Novo agendamento';fillContactSelect('appointment-contact',a?.contact_id||'');$('appointment-service').value=a?.service_label||'';$('appointment-start').value=localInputDate(a?.starts_at)||localInputDate(new Date(Date.now()+3600000));$('appointment-end').value=localInputDate(a?.ends_at)||localInputDate(new Date(Date.now()+5400000));$('appointment-location').value=a?.location_label||'';$('appointment-status').value=a?.status||'scheduled';setStatus('appointment-status-message','');openModal('appointment-modal')}
 async function appointmentConflict(start,end,id){const q=sb.from('clinic_crm_appointments').select('id').eq('clinic_id',clinicId).lt('starts_at',end).gt('ends_at',start).neq('status','cancelled');const {data,error}=await q;if(error)throw error;return (data||[]).some(x=>x.id!==id)}
 $('appointment-form').addEventListener('submit',async e=>{e.preventDefault();try{const id=$('appointment-id').value,start=new Date($('appointment-start').value),end=new Date($('appointment-end').value);if(!(start<end))throw new Error('O fim precisa ser posterior ao início.');if(await appointmentConflict(start.toISOString(),end.toISOString(),id))throw new Error('Já existe um agendamento que se sobrepõe a esse horário.');const row={clinic_id:clinicId,contact_id:$('appointment-contact').value,service_label:$('appointment-service').value.trim(),starts_at:start.toISOString(),ends_at:end.toISOString(),location_label:$('appointment-location').value.trim()||null,status:$('appointment-status').value,created_by:currentUserId};const res=id?await sb.from('clinic_crm_appointments').update(row).eq('id',id).eq('clinic_id',clinicId):await sb.from('clinic_crm_appointments').insert(row);if(res.error)throw res.error;await audit(id?'appointment_updated':'appointment_created','appointment',id||null,{starts_at:row.starts_at,status:row.status});closeModal('appointment-modal');await loadData();setStatus('app-status','Agendamento salvo.','success')}catch(err){setStatus('appointment-status-message','Não foi possível salvar: '+(err.message||''),'error')}});
