 function openInteractionModal(id=''){const i=interactions.find(x=>x.id===id);$('interaction-form').reset();$('interaction-id').value=i?.id||'';$('interaction-title').textContent=i?'Editar interação':'Registrar interação';fillContactSelect('interaction-contact',i?.contact_id||'');$('interaction-channel').value=i?.channel||'whatsapp';$('interaction-direction').value=i?.direction||'outbound';$('interaction-summary').value=i?.summary||'';$('interaction-outcome').value=i?.outcome||'';$('interaction-date').value=localInputDate(i?.occurred_at)||localInputDate(new Date());setStatus('interaction-status','');openModal('interaction-modal')}
