 // Orçamentos de serviços, com impressão e atualização do pipeline quando aprovados.
 function openQuoteModal(id=''){const q=quotes.find(x=>x.id===id);$('quote-form').reset();$('quote-id').value=q?.id||'';$('quote-title').textContent=q?'Editar orçamento':'Novo orçamento';fillContactSelect('quote-contact',q?.contact_id||'');$('quote-opportunity').innerHTML='<option value="">Sem oportunidade vinculada</option>'+opportunities.map(o=>'<option value="'+esc(o.id)+'" '+(q?.opportunity_id===o.id?'selected':'')+'>'+esc(o.title)+'</option>').join('');$('quote-name').value=q?.title||'';$('quote-subtotal').value=q?.subtotal??0;$('quote-discount').value=q?.discount??0;$('quote-valid').value=q?.valid_until||'';$('quote-status').value=q?.status||'draft';$('quote-notes').value=q?.notes||'';setStatus('quote-status-message','');openModal('quote-modal')}
 $('quote-form').addEventListener('submit',async e=>{e.preventDefault();try{const id=$('quote-id').value,subtotal=Number($('quote-subtotal').value),discount=Number($('quote-discount').value),status=$('quote-status').value;if(subtotal<0||discount<0||discount>subtotal)throw new Error('O desconto deve ser menor ou igual ao subtotal.');const row={clinic_id:clinicId,contact_id:$('quote-contact').value,opportunity_id:$('quote-opportunity').value||null,title:$('quote-name').value.trim(),items:[{description:$('quote-name').value.trim(),quantity:1,unit_price:subtotal}],subtotal,discount,total:subtotal-discount,status,valid_until:$('quote-valid').value||null,notes:$('quote-notes').value.trim()||null,created_by:currentUserId};const res=id?await sb.from('clinic_crm_quotes').update(row).eq('id',id).eq('clinic_id',clinicId).select('id').single():await sb.from('clinic_crm_quotes').insert(row).select('id').single();if(res.error)throw res.error;const quoteId=res.data?.id||id;if(status==='approved'&&row.opportunity_id){const upd=await sb.from('clinic_crm_opportunities').update({stage:'won'}).eq('id',row.opportunity_id).eq('clinic_id',clinicId);if(upd.error)throw upd.error;await audit('opportunity_stage_changed','opportunity',row.opportunity_id,{to:'won',reason:'quote_approved'})}await audit(id?'quote_updated':'quote_created','quote',quoteId||null,{status,total:row.total});closeModal('quote-modal');await loadData();setStatus('app-status','Orçamento salvo.','success')}catch(err){setStatus('quote-status-message','Não foi possível salvar: '+(err.message||''),'error')}});
 $('quotes-table').addEventListener('click',e=>{const b=e.target.closest('[data-quote-action]');if(!b)return;if(b.dataset.quoteAction==='edit')openQuoteModal(b.dataset.id);if(b.dataset.quoteAction==='delete')deleteRecord('clinic_crm_quotes',b.dataset.id,'quote');if(b.dataset.quoteAction==='print')printQuote(b.dataset.id)});
 function printQuote(id){const q=quotes.find(x=>x.id===id);if(!q)return;const c=contacts.find(x=>x.id===q.contact_id);const w=window.open('','_blank');if(!w){setStatus('app-status','Permita pop-ups para imprimir o orçamento.','error');return}w.opener=null;w.document.write('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Orçamento</title><style>body{font:14px Arial;padding:32px;color:#222}h1{font-size:24px}table{width:100%;border-collapse:collapse}td{padding:10px;border-bottom:1px solid #ddd}</style><h1>'+esc(clinicName)+'</h1><h2>Orçamento '+String(q.quote_number||'')+'</h2><p>Cliente: '+esc(c?.full_name||'—')+'</p><p>'+esc(q.title)+'</p><table><tr><td>Subtotal</td><td>'+money(q.subtotal)+'</td></tr><tr><td>Desconto</td><td>'+money(q.discount)+'</td></tr><tr><td><strong>Total</strong></td><td><strong>'+money(q.total)+'</strong></td></tr></table><p>Validade: '+esc(q.valid_until||'Não informada')+'</p><p>'+esc(q.notes||'')+'</p><script>window.onload=()=>window.print()<\/script></html>');w.document.close()}
