 $('member-form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;setStatus('member-status','Enviando convite…');try{const {data:sessionData}=await sb.auth.getSession();const {data,error}=await sb.functions.invoke('clinic-crm-invite-member',{body:{clinic_id:clinicId,display_name:$('member-name').value.trim(),email:$('member-email').value.trim(),role:$('member-role').value}});if(error)throw error;if(data?.error)throw new Error(data.error);await audit('member_invited','member',data.member?.id||null,{email:$('member-email').value.trim(),role:$('member-role').value});closeModal('member-modal');await loadData();setStatus('app-status',data.message||'Convite enviado.','success')}catch(err){setStatus('member-status','Não foi possível convidar: '+(err.message||'verifique a configuração de e-mail do Supabase.'));}finally{btn.disabled=false}});
 function renderMembers(){const el=$('members-list');if(!el)return;if(!['owner','admin'].includes(currentRole)){el.innerHTML='<div class="empty">Somente proprietários e administradores podem gerenciar a equipe.</div>';return}const roleOptions=m=>['admin','manager','reception','clinician','finance','marketing'].map(r=>'<option value="'+r+'" '+(m.role===r?'selected':'')+'>'+esc(roleLabel(r))+'</option>').join('');el.innerHTML=members.length?members.map(m=>'<div class="member-row"><div><strong>'+esc(m.display_name||m.email||'Usuário')+'</strong><div class="subline">'+esc(m.email||'E-mail não informado')+' · '+esc(roleLabel(m.role))+' · '+(m.active?'Ativo':'Inativo')+'</div></div><div class="row-actions">'+(m.user_id!==currentUserId?'<select class="tiny-button" aria-label="Perfil de '+esc(m.email||m.display_name)+'" data-member-role="'+esc(m.id)+'">'+roleOptions(m)+'</select><button class="tiny-button" data-member-action="save-role" data-id="'+esc(m.id)+'">Salvar perfil</button><button class="tiny-button" data-member-action="toggle" data-id="'+esc(m.id)+'" data-active="'+String(m.active)+'">'+(m.active?'Desativar':'Reativar')+'</button>':'<span class="pill green">Você · '+esc(roleLabel(m.role))+'</span>')+'</div></div>').join(''):'<div class="empty">Nenhum usuário encontrado.</div>'}
 $('members-list').addEventListener('click',async e=>{const roleButton=e.target.closest('[data-member-action="save-role"]');if(roleButton){const m=members.find(x=>x.id===roleButton.dataset.id),select=$('members-list').querySelector('[data-member-role="'+roleButton.dataset.id+'"]');if(!m||!select)return;const role=select.value;if(!['admin','manager','reception','clinician','finance','marketing'].includes(role)){setStatus('app-status','Perfil inválido.','error');return}const {error}=await sb.from('clinic_crm_members').update({role}).eq('id',m.id).eq('clinic_id',clinicId);if(error){setStatus('app-status','Não foi possível alterar o perfil: '+error.message,'error');return}await audit('member_role_changed','member',m.id,{from:m.role,to:role});await loadData();setStatus('app-status','Perfil atualizado.','success');return}const b=e.target.closest('[data-member-action="toggle"]');if(!b)return;const m=members.find(x=>x.id===b.dataset.id);if(!m||m.user_id===currentUserId)return;const active=m.active!==true;if(!confirm((active?'Reativar':'Desativar')+' acesso de '+(m.display_name||m.email)+' nesta clínica?'))return;const {error}=await sb.from('clinic_crm_members').update({active}).eq('id',m.id).eq('clinic_id',clinicId);if(error){setStatus('app-status','Não foi possível alterar o acesso: '+error.message,'error');return}await audit(active?'member_activated':'member_deactivated','member',m.id,{email:m.email});await loadData()});
